1|import "server-only";
2|import { createHmac } from "node:crypto";
3|import { QUOTA_TTL_SEC, overQuota, quotaKeys } from "@/core/images";
4|import type { KV } from "@/core/images";
5|
6|// Per-person quota: 5 new images per day, counted by hashed IP and by
7|// anonymous cookie, whichever runs out first. Day keys are UTC dates.
8|export function utcDay(now: Date = new Date()): string {
9|  return now.toISOString().slice(0, 10);
10|}
11|
12|export function hashIp(ip: string, salt: string): string {
13|  return createHmac("sha256", salt).update(ip).digest("hex");
14|}
15|
16|export function clientIp(forwardedFor: string | null | undefined): string {
17|  return (forwardedFor ?? "").split(",")[0]?.trim() || "unknown";
18|}
19|
20|export async function checkQuota(
21|  kv: KV,
22|  keys: { ip: string; anon: string },
23|): Promise<{ ok: true } | { ok: false }> {
24|  const ipCount = await kv.incr(keys.ip);
25|  await kv.expire(keys.ip, QUOTA_TTL_SEC);
26|  const anonCount = await kv.incr(keys.anon);
27|  await kv.expire(keys.anon, QUOTA_TTL_SEC);
28|  if (overQuota(ipCount) || overQuota(anonCount)) {
29|    await kv.decr(keys.ip);
30|    await kv.decr(keys.anon);
31|    return { ok: false };
32|  }
33|  return { ok: true };
